/** Shared demo accounts of a public demo deployment ({ enabled: false } everywhere else). */
export function useDemoInfo() {
  return useQuery({
    queryKey: ['demo'],
    queryFn: () => fetchApi('/auth/demo'),
    staleTime: Infinity,
    retry: false,
  });
}

export function isDemoUser(demo, user) {
  return Boolean(demo?.enabled && user && demo.accounts.some(a => a.username === user.username));
}
